#include <stdint.h>

int main(void) {
    uint32_t state = 0xACE1u;
    int steps = 500000;
    unsigned seen = 0u;

    for (int i = 0; i < steps; ++i) {
        uint32_t bit = ((state >> 0) ^ (state >> 2) ^ (state >> 3) ^ (state >> 5)) & 1u;
        state = (state >> 1) | (bit << 15);
        state &= 0xFFFFu;
        if ((state & 0xFFu) == 0x42u) {
            seen++;
        }
    }

    printf("%u %u\n", (unsigned)state, seen);
    return 0;































}

